/**
 * frontend/src/components/Dashboard.jsx
 * VERSION DEBUG - Pour voir exactement ce que renvoient les APIs
 */

import React, { useState, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const Dashboard = () => {
  const [logRes, setLogRes] = useState(null);
  const [statsRes, setStatsRes] = useState(null);
  const [statusRes, setStatusRes] = useState(null);
  const [loading, setLoading] = useState(true);

  const loadDebug = async () => {
    try {
      setLoading(true);
      const [log, stats, status] = await Promise.all([
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStats(),
        attendanceAPI.getStatus(),
      ]);

      setLogRes(log);
      setStatsRes(stats);
      setStatusRes(status);

      console.log("=== DEBUG LOG ===", log);
      console.log("=== DEBUG STATS ===", stats);
      console.log("=== DEBUG STATUS ===", status);
    } catch (err) {
      console.error("Debug error:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadDebug();
  }, []);

  if (loading) return <div style={{ padding: 50 }}>Chargement en cours...</div>;

  return (
    <div style={{ padding: 30, fontFamily: 'Arial' }}>
      <h1>Dashboard Debug Mode</h1>
      <button onClick={loadDebug} style={{ padding: '10px 20px', marginBottom: 20 }}>
        Rafraîchir Debug
      </button>

      <h2>1. Today Log (Derniers scans)</h2>
      <pre style={{ background: '#f0f0f0', padding: 15, borderRadius: 8 }}>
        {JSON.stringify(logRes, null, 2)}
      </pre>

      <h2>2. Attendance Stats (Analyse pipeline)</h2>
      <pre style={{ background: '#f0f0f0', padding: 15, borderRadius: 8 }}>
        {JSON.stringify(statsRes, null, 2)}
      </pre>

      <h2>3. Status (Liste étudiants)</h2>
      <pre style={{ background: '#f0f0f0', padding: 15, borderRadius: 8 }}>
        {JSON.stringify(statusRes, null, 2)}
      </pre>
    </div>
  );
};

export default Dashboard;
